INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-folk-merchant-benno', 'ws-artemis-store', 'asset-folk-merchant-benno', 'folk-merchant-benno', '상인 벤노', '키 1.77 m 인 사람 모델입니다. 챙모자, 조끼, 가죽 가방, 덥수룩한 수염. 폴리곤 5,933개, 재질 1개, 텍스처 없이 정점 색입니다. 뼈대는 68개이고 이름은 Mixamo/Unity 휴머노이드 표기입니다 — Hips, Spine, Spine1, Spine2, Neck, Head, 좌우 Shoulder·Arm·ForeArm·Hand, 손가락마다 마디 세 개, 좌우 UpLeg·Leg·Foot·ToeBase. 여섯 캐릭터가 뼈 이름과 기본 자세를 공유하므로 한 동작을 여섯에 그대로 걸 수 있습니다. 동작 8개가 파일 안에 들어 있습니다 — 대기 3.60초, 걷기 0.92초, 달리기 0.70초, 손 흔들기 2.40초, 바구니 들고 대기 3.20초, 괭이질 1.10초, 물주기 1.60초, 수확 1.40초. 괭이·물뿌리개·바구니는 오른손의 전용 뼈(ToolHoe, ToolCan, ToolBasket)에 달려 있고, 그 도구를 쓰는 동작에서만 크기가 커집니다. 기본 자세와 대기·걷기·달리기·손 흔들기에서는 빈손입니다. 발바닥 최저점은 기본 자세에서 y = 0 에서 1.0 mm 안에 있습니다. 동작 여덟 개를 각각 여덟 위상에서 잘라 팔·다리·도구가 서로를 뚫고 지나가는지 삼각형 단위로 확인했습니다 — 자세 64개에서 뚫고 지나간 삼각형은 없습니다.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
