INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-kit-harvest-folk', 'ws-artemis-store', 'asset-kit-harvest-folk', 'kit-harvest-folk', '하베스트 포크 캐릭터 키트', '6명이 1.5 m 간격으로 한 줄로 선 파일 하나입니다 — 농부 토마스, 재배가 이다, 어르신 오토, 식물학자 미라, 상인 벤노, 아이 핌. 뼈대와 동작이 그대로 들어 있어 여섯이 동시에 움직입니다. 뼈 이름 앞에는 그 캐릭터의 슬러그가 붙습니다(farmer-tomas_Hips). 폴리곤 34,246개, 재질 1개, 동작 8개 — 대기 3.60초, 걷기 0.92초, 달리기 0.70초, 손 흔들기 2.40초, 바구니 들고 대기 3.20초, 괭이질 1.10초, 물주기 1.60초, 수확 1.40초. 가로 8.63 m, 높이 1.87 m 입니다. 낱개로 받을 때는 부품 상품 여섯 개가 각각 자기 뼈대와 같은 동작 여덟 개를 갖습니다.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
